def separate_paren_groups(paren_string):
    brace_stack = []
    len_string = len(paren_string)
    new_string = []
    
    for i in range(len(paren_string)):
        if len_string == i and len(brace_stack) > 0:
            new_string += ')' * len(brace_stack)
            break
        elif len_string == i:
            break
        elif paren_string[i] in ['(', '[']:
            brace_stack.append(paren_string[i])
        elif (paren_string[i] == ')' and paren_string[i-1] == '(') or (paren_string[i] == ']' and paren_string[i-1] == '['):
            brace_stack.pop()
        else:
            new_string += paren_string[i]
        
    return [new_string, ')' * len(brace_stack)]

