    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    """
    if n <= 0:
        raise ValueError('Expected n to be positive integer')
    elif n == 1:
        return 2
    last_num = 0
    next_num = 1
    fib_number = 1

    for _ in range(1, n):
        last_num, next_num = next_num, last_num + next_num

        if all(next_num % x != 0 for x in range(2, next_num)):
            fib_number += 1

