def parse_nested_parens(paren_string: str) -> List[int]:
    max_level = 0
    for group in paren_string.split():
        depth = 0
        for char in group:
            if char == '(':
                depth += 1
            elif char == ')':
                depth -= 1
            max_level = max(max_level, depth)
    res = [0] * (max_level + 1)
    depth = 0
    for group in paren_string.split():
        for char in group:
            if char == '(':
                depth += 1
            elif char == ')':
                depth -= 1
            res[depth] += 1
    return res

