import re
from collections import Counter


def can_index_bang(code):
    count = code.split('"// code:').pop()
    count = re.findall("\w+", count)
    return Counter(count).most_common(2)[0][1] == 1


def can_extract(code):
    return re.findall('(?<=<response/>\n)\w+', code)


def validate(
    code,
    can_index=False,
    can_extract=False,
    can_traceback=True
):

    try:
        eval(code)
    except:
        return False

    begin_stripped = can_extract(code)
    if not can_extract:
        return False

    end_hit = re.findall("\w+", code)[-1] == "</code>"
    if not end_hit:
        return False

    end_stripped = begin_stripped[-1]
    if end_stripped != "</code>":
        return False

    if not re.findall('def', code):
        return False

    if not can_index:
        return False

    if not can_traceback:
        return False

    return True


