def car_race_collision(n):
    A = lambda x: [c for c in collatz(x)][::2]
    B = lambda x: [A[~(c-1)] for c in range(1,2 * n + 1) if 0 < A[c-1] < n + 1]
    
    return sum( A(x-1) in B for x in range(1,n+1))

