### Solution:
``` python
def pairs_sum_to_zero(l):
    """
    pairs_sum_to_zero takes a list of integers as an input.
    it returns True if there are two distinct elements in the list that
    sum to zero, and False otherwise.
    """

    # empty array of len(l) filled with booleans, True if the elemnt is already seen, False if no.
    seen = [False] * len(l);

    # iterate over every element two at a time.
    for idx1, elem1 in enumerate(l[:-1]):
        # iterate over every subsequent element starting at the second position.
        for idx2, elem2 in enumerate(l[idx1 + 1:]):
            # check for elem1 + elem2 = 0, and remember that elem1 or elem2 has already been seen.
            if (elem1 + elem2 == 0) & (seen[idx1]  | seen[idx2]):
                return True;
            else:
                seen[idx1] = True;
                seen[idx2] = True;
    # no two pair sums to zero
    return False;
