def remove_duplicates(numbers):
    seen = set()  # O(1)
    result = [] # O(n)
    for n in numbers:   # O(n)
        if n not in seen:
            result.append(n) # 1apnd O(1)
            seen.add(n) # add O(1)
        # disregard the else condition as:
        # the n is in seen so will not append
    return result

