def factorize(n: int) -> List[int]:
    factors: List[int] = []
    d, r = divmod(n, 2)
    while d > 1 and r == 0:
        factors.append(2)
        d, r = divmod(d, 2)
    for i in range(3, int(n ** 0.5) + 1, 2):
        d, r = divmod(n, i)
        while d > 1 and r == 0:
            factors.append(i)
            d, r = divmod(d, i)
    if r > 1:
        return factors + [n]
    return factors

