def string_xor(a: str, b: str) -> str:
    """ Input are two strings a and b consisting only of 1s and 0s.
    Perform binary XOR on these inputs and return result also as a string.
    >>> string_xor('010', '110')
    '100'
    """
    
    len_a = len(a)
    len_b = len(b)
    
    if len_a == len_b == 0:
        return ''
    
    result = ''
    bit_xor = '0' if a[0] == b[0] else '1'
    for i in range(min(len_a, len_b)):
        if a[i] == b[i]:
            result += '0'
        else:
            result += bit_xor
    if len_a > len_b:
        return result + a[len_b:]
    elif len_b > len_a:
        return result + b[len_a:]
    
    return result
