def generate_solution(comment: str) -> str:
    """ A function to generate a valid solution from a input comment,
    it assumes that the first block of the comment is the question
    and the second is the solution, also, it is expected that all
    lines in the second block end with </code>
    So, I am handling this through a heuristic that removes everything in between block delimiters.
    If the comment is empty, then we return None."""
    lines = comment.splitlines()
    if len(lines) == 0:
        return None
    beg = lines[0] if lines[0] in ["""**Instruction**""", """**Specifications**"""] else None
    end = lines[2] if lines[2] in [
        """**Instruction**""", """**Specifications**"""
    ] else None
    res = [line for line in lines[2:] if beg and end and not line.startswith("```") and not line.endswith("</code>")]
    return blackify("\n".join(res))


