def common_letters(a: str, b: str):
    def counter(s: str):
        d = dict(zip(string.ascii_lowercase, [0] * 26))
        for c in s:
            d[c] += 1
        return d
    def mismatch(d1: dict, d2: dict):
        for k, v in d2.items():
            if not d1[k] or d1[k] != v:
                return True
        return False

    a_dict = counter(a)
    b_dict = counter(b)
    return not mismatch(a_dict, b_dict)
