class Solution:
    def prime_fib(self, n):
        md = {0: 1, 1: 1}
        for i in range(2, n + 1):
            md[i] = self.lucas(i, md)
            yield md[i]
    def lucas(self, n, a):
        if n in a: return a[n]
        a[n] = a[n - 1] + a[n - 2]
        return a[n]

