def subset_with_zero_sum(l: list) -> bool:
    """
    subset_with_zero_sum takes a list of integers as an input.
    it returns True if there is a subset that sums to zero,
    and False otherwise.

    >>> subset_with_zero_sum([1, 3, 5, 0])
    True
    >>> subset_with_zero_sum([1, 3, -2, 1])
    True
    >>> subset_with_zero_sum([1, 2, 3, 7])
    False
    >>> subset_with_zero_sum([2, 4, -3, 3, 9, 7])
    True
    >>> subset_with_zero_sum([1])
    False
    """
    l = sorted(l, key=abs)
    if sum([l[0], l[-1]]) == 0:
        return True
    for i in range(1, len(l) - 1):
        try:
            l.remove(l[0])
            if subset_with_zero_sum(l):
                return True
        except:
            pass
    return False

