from typing import List


def parse_nested_parens(paren_string):
    """ Peel open parens until inner parens are balanced;
    Make recursive call;
    Add 1 for pair peeled open;
    Return."""
    if paren_string[0] != '(':
        raise ValueError('Illegal paren string')
    start = paren_string.find('(')
    how_deep = 0
    for i in range(start, len(paren_string)):
        if paren_string[i] == '(':
            how_deep += 1
        elif paren_string[i] == ')':
            how_deep -= 1
        elif paren_string[i] == ' ':
            raise ValueError('Illegal paren string')
        if how_deep == 0:
            depth += 1
            break
    return how_deep + parse_nested_parens

