def _trim_six_spaces(level, line):
    line_list_orig = line.split('\n', 1)
    line = line_list_orig[0]
    line_list = line.split()
    level_count = len(level)
    line_list = line_list[0:level_count] + line_list[level_count + 1:]
    return ' '.join(line_list)


def _subtract_double_quotes(level, line):
    line_list_orig = line.split('\n', 1)
    line = line_list_orig[0]
    line_list = line.split()

    remove_right_spaces = 2 * len('""')
    line_list = line_list[0:len(level) + 1] + line_list[len(level) + 2:]
    level += '""' * remove_right_spaces
    return level + ' '.join(line_list)


def _remove_indented_spacing_helper(line, level):
    return _trim_six_spaces(level, _subtract_double_quotes(level, line))


def _remove_indented_spacing(string, level):
    return re.sub(r'^' + level + r'\s*"""[\s\S]*?"""', _remove_indented_spacing_helper, string, flags=re.MULTILINE)


def remove_indented_spacing(string):
    return _remove_indented_spacing(string, '    ')


def restore_indented_spacing(string):
    return _remove_indented_spacing(string, '')


