def longest(strings: List[str]) -> Optional[str]:
    """ Out of list of strings, return the longest one. Return the first one in case of multiple
    strings of the same length. Return None in case the input list is empty.
    """
    if not strings:
        return None
    sorted_strings = sorted(strings, key=len)[::-1]
    for current_string in sorted_strings:
        # Stop searching if next strings are not longer than the current.
        if current_string == sorted_strings[0] and len(strings) > 1:
            return current_string
        # Returning the check the first has exact same length as the current.
        if len(current_string) == len(sorted_strings[0]):
            return current_string
    # If none suits the requirements, then returning the first string in the list.
    return sorted_strings[0]

