from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    """ Input to this function is a string representing multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    E.g. (()()) has a maximum of two levels of nesting, while ((())) has three.
    """
    output = []
    stack = []
    nested = 0
    current_paren_string = ''
    open_close = 0

    for i, char in enumerate(paren_string):
        current_paren_string += char
        if char == '(':
            nested += 1
            if not stack:
                if open_close > 0:
                    pass  # no-op
                else:
                    open_close = nested
                stack.append(i)
            else:
                stack.append(i)
        elif char == ')':
            nested -= 1
            if not nested:
                start_index = stack.pop()
                output.append(i - start_index)
        if nested:
            if nested == 0:
                pass  # no-op
            elif nested == 1:
                nested = 0   

    return output

